def get_embedding(text: str, api_key: str) -> list:
    """Gemini embedding API でテキストをベクトル化する（標準ライブラリのみ）"""
    url = f"{GEMINI_API_BASE}/{_EMBEDDING_MODEL}:embedContent?key={api_key}"
    payload = json.dumps({
        "content": {"parts": [{"text": text[:30000]}]}
    }).encode("utf-8")

    max_retries = 5
    base_backoff = 10.0  # より保守的なバックオフ
    for attempt in range(max_retries):
        req = urllib.request.Request(
            url, data=payload,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                data = json.loads(resp.read().decode("utf-8"))
                return data.get("embedding", {}).get("values", [])
        except urllib.error.HTTPError as e:
            if e.code == 429 and attempt < max_retries - 1:
                wait_time = base_backoff * (2 ** attempt)
                log.info({"event": "embedding_429_wait", "attempt": attempt + 1, "wait": wait_time})
                time.sleep(wait_time)
                continue
            log.warning({"event": "embedding_error", "error": str(e)})
            break
        except Exception as e:
            log.warning({"event": "embedding_error", "error": str(e)})
            break
    return []

